/* The error checking of the services that exist only with dynamic bidi text
   support: gx_utility_bidi_paragraph_reorder, its _ext form,
   gx_utility_bidi_resolved_text_info_delete and
   gx_display_language_direction_table_set.

   The bidi character test calls the utility services by their _gx_ names, so
   nothing went through their checking. Each is called here once per check it
   makes and once with valid arguments, so that it also returns the status of
   the service it checks for. The caller checks are reached as in
   guix_gxe_api_error_checking_coverage_no_output, by forging the timer thread
   as the current thread with the system state set to 1 and to -1; each forged
   call returns at the caller check, and both are restored before the next
   call. */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "tx_api.h"
#include "gx_api.h"
#include "gx_system.h"
#include "gx_validation_utility.h"

TEST_PARAM test_parameter = {
    "guix_dynamic_bidi_api_error_checking_no_output", /* Test name */
    0, 0, 0, 0  /* Define the coordinates of the capture area.*/
};

int main(int argc, char ** argv)
{
    /* Start ThreadX system */
    tx_kernel_enter();
    return(0);
}

#if defined(GX_DISABLE_ERROR_CHECKING)
VOID tx_application_define(void *first_unused_memory)
{
    exit(0);
}
#else
static UINT failed_tests = 0;
static INT  allocated_blocks = 0;
extern volatile ULONG      _tx_thread_system_state;
extern volatile TX_THREAD  *_tx_thread_current_ptr;
extern TX_THREAD            _tx_timer_thread;

static VOID *test_memory_allocate(ULONG size)
{
VOID *memory = malloc(size);

    if (memory)
    {
        allocated_blocks++;
    }

    return memory;
}

static VOID test_memory_free(VOID *memory)
{
    allocated_blocks--;
    free(memory);
}

/* One paragraph of three left-to-right characters, unwrapped, comes back as
   one line holding the same three characters whatever the base direction.  */
static VOID resolved_text_check(GX_BIDI_RESOLVED_TEXT_INFO *resolved_head)
{
    EXPECT_EQ(GX_TRUE, resolved_head != GX_NULL);

    if (resolved_head)
    {
        EXPECT_EQ(GX_TRUE, resolved_head -> gx_bidi_resolved_text_info_next == GX_NULL);
        EXPECT_EQ(1, resolved_head -> gx_bidi_resolved_text_info_total_lines);
        EXPECT_EQ(3, resolved_head -> gx_bidi_resolved_text_info_text[0].gx_string_length);
        EXPECT_EQ(0, memcmp(resolved_head -> gx_bidi_resolved_text_info_text[0].gx_string_ptr, "abc", 3));
    }
}

VOID tx_application_define(void *first_unused_memory)
{
UINT                        status;
ULONG                       saved_state;
TX_THREAD                  *saved_thread;
GX_BIDI_TEXT_INFO           text_info;
GX_BIDI_RESOLVED_TEXT_INFO *resolved_head = GX_NULL;

    /* gx_display_language_direction_table_set: the caller check.  */
    saved_state = _tx_thread_system_state;
    saved_thread = (TX_THREAD *)_tx_thread_current_ptr;
    _tx_thread_current_ptr = &_tx_timer_thread;

    _tx_thread_system_state = 1;
    status = gx_display_language_direction_table_set(GX_NULL, GX_NULL, 0);
    EXPECT_EQ(GX_CALLER_ERROR, status);
    _tx_thread_system_state = -1;
    status = gx_display_language_direction_table_set(GX_NULL, GX_NULL, 0);
    EXPECT_EQ(GX_CALLER_ERROR, status);

    _tx_thread_system_state = saved_state;
    _tx_thread_current_ptr = saved_thread;

    /* gx_display_language_direction_table_set: the display pointer.  */
    status = gx_display_language_direction_table_set(GX_NULL, GX_NULL, 0);
    EXPECT_EQ(GX_PTR_ERROR, status);

    /* The bidi utility services allocate their results.  */
    status = gx_system_initialize();
    EXPECT_EQ(GX_SUCCESS, status);
    status = gx_system_memory_allocator_set(test_memory_allocate, test_memory_free);
    EXPECT_EQ(GX_SUCCESS, status);

    memset(&text_info, 0, sizeof(GX_BIDI_TEXT_INFO));
    text_info.gx_bidi_text_info_text.gx_string_ptr = "abc";
    text_info.gx_bidi_text_info_text.gx_string_length = 3;
    text_info.gx_bidi_text_info_font = GX_NULL;
    text_info.gx_bidi_text_info_display_width = -1;

    /* gx_utility_bidi_paragraph_reorder.  */
    status = gx_utility_bidi_paragraph_reorder(GX_NULL, &resolved_head);
    EXPECT_EQ(GX_PTR_ERROR, status);
    status = gx_utility_bidi_paragraph_reorder(&text_info, GX_NULL);
    EXPECT_EQ(GX_PTR_ERROR, status);
    status = gx_utility_bidi_paragraph_reorder(&text_info, &resolved_head);
    EXPECT_EQ(GX_SUCCESS, status);
    resolved_text_check(resolved_head);

    /* gx_utility_bidi_resolved_text_info_delete.  */
    status = gx_utility_bidi_resolved_text_info_delete(GX_NULL);
    EXPECT_EQ(GX_PTR_ERROR, status);
    status = gx_utility_bidi_resolved_text_info_delete(&resolved_head);
    EXPECT_EQ(GX_SUCCESS, status);
    EXPECT_EQ(GX_TRUE, resolved_head == GX_NULL);
    EXPECT_EQ(0, allocated_blocks);

    /* gx_utility_bidi_paragraph_reorder_ext, right to left.  */
    text_info.gx_bidi_text_info_direction = GX_LANGUAGE_DIRECTION_RTL;
    status = gx_utility_bidi_paragraph_reorder_ext(GX_NULL, &resolved_head);
    EXPECT_EQ(GX_PTR_ERROR, status);
    status = gx_utility_bidi_paragraph_reorder_ext(&text_info, GX_NULL);
    EXPECT_EQ(GX_PTR_ERROR, status);
    status = gx_utility_bidi_paragraph_reorder_ext(&text_info, &resolved_head);
    EXPECT_EQ(GX_SUCCESS, status);
    resolved_text_check(resolved_head);

    status = gx_utility_bidi_resolved_text_info_delete(&resolved_head);
    EXPECT_EQ(GX_SUCCESS, status);
    EXPECT_EQ(0, allocated_blocks);

    if (failed_tests)
    {
        gx_validation_print_test_result(TEST_FAIL);
    }
    else
    {
        gx_validation_print_test_result(TEST_SUCCESS);
    }

    exit(failed_tests);
}
#endif /* defined(GX_DISABLE_ERROR_CHECKING) */

